bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Check if the file type is dangerous based on its extension
    const char* file_extension = GetFileExtension(suggested_path);
    bool is_extension = IsExtensionFile(file_extension);
    bool is_extension_install_allowed = IsOffStoreExtensionInstallAllowed();

    if (is_extension && !is_extension_install_allowed) {
        return true;
    }

    // Check if the user gesture indicates a potential risk
    bool has_user_gesture = download.has_user_gesture;

    // Evaluate referrer context
    if (!visited_referrer_before && !has_user_gesture) {
        return true;
    }

    // Check if the file's content is considered dangerous
    bool is_file_dangerous = IsDangerousFileType(file_extension);

    return is_file_dangerous;
}

bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
  // Default to dangerous if it's an extension without approval
  if (download.is_extension && !download.has_user_approval) {
    return true;
  }

  // Check if the file is of a known dangerous type
  const char* file_extension = FilePath_GetExtension(suggested_path);
  if (file_extension && (strcmp(file_extension, ".exe") == 0 ||
                          strcmp(file_extension, ".bat") == 0 ||
                          strcmp(file_extension, ".dll") == 0 ||
                          strcmp(file_extension, ".scr") == 0 ||
                          strcmp(file_extension, ".sh") == 0 ||
                          strcmp(file_extension, ".py") == 0)) {
    return true;
  }

  // If the user hasn't visited the referrer before, it's more dangerous
  if (!visited_referrer_before && !download.has_user_gesture) {
    return true;
  }

  return false;
}

bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
  // Check if off-store extension installation is enabled and the download is an unapproved extension
  if (download.IsExtension() && !download.IsExtensionApproved() && !AreOffStoreExtensionsEnabled()) {
    return true;
  }

  // Check if the file is deemed dangerous based on its extension
  if (IsDangerousExtension(suggested_path)) {
    return true;
  }

  // If the user has not interacted with the page, it's considered unsafe
  if (!download.IsUserInitiated() && !visited_referrer_before) {
    return true;
  }

  return false;
}

bool IsDangerousDownload(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Check if it's an extension without approval
    if (download.type == EXTENSION && !download.approved) {
        // If off-store extension installations are not enabled, it's dangerous
        if (!IsOffStoreExtensionInstallationEnabled()) {
            return true;
        }
    }

    // Check file extension danger
    const char* file_extension = GetFileExtension(suggested_path);
    if (IsDangerousFileExtension(file_extension)) {
        return true;
    }

    // If the user didn't gesture for the download and hasn't visited the referrer before
    if (!download.user_initiated && !visited_referrer_before) {
        return true;
    }

    return false;
}

bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Default to safe
    bool is_dangerous = false;

    // Check if off-store extension installations are enabled and the download is an extension without approval
    if (download.is_extension && !download.is_approved) {
        is_dangerous = true;
    }

    // Evaluate based on file extension
    const char* file_extension = FilePath_GetExtension(suggested_path);
    if (file_extension && (String_Equals(file_extension, ".exe") ||
                           String_Equals(file_extension, ".bat") ||
                           String_Equals(file_extension, ".sh") ||
                           String_Equals(file_extension, ".dll") ||
                           String_Equals(file_extension, ".js"))) {
        is_dangerous = true;
    }

    // If the user has not visited the referrer before, it is more likely to be dangerous
    if (!visited_referrer_before) {
        is_dangerous = true;
    }

    // Evaluate based on user gestures
    if (!download.has_user_gesture) {
        is_dangerous = true;
    }

    return is_dangerous;
}
